/**
 * world-markets/WorldMap — the WORLD MARKETS MAP module
 * (docs/insights/world-markets-map-spec.md M1–M17).
 *
 * A presentation layer over the section's existing data: the same stored
 * snapshot, the same registry, ZERO new KV operations and ZERO network
 * requests beyond the two bundled static assets (B3: the land SVG and the
 * flags sprite, fetched only when the module is about one screen from the
 * viewport). The dot positions are build-time output (world-map-geo.json,
 * generated by `pnpm --filter @currena/web run build:map`); the card
 * positions and thresholds live in world-map-config.ts — the module reads
 * ONLY that config (spec §4).
 *
 * Layout (M2): a container query on the module's own width — ≥960px the
 * map layout (map + callout cards), below it the list layout (the same
 * map, smaller, no cards — the existing explorer list below carries the
 * data). The map box keeps its aspect ratio and stays LTR in Farsi
 * (geography does not mirror, M15) while the header, summary, legend and
 * each card's content mirror with the section's direction.
 *
 * States (M17): loading (grey land, grey hollow dots, no numbers, height
 * reserved), one index missing ("—" + No data, neutral country), one
 * index old (same + Old data), whole payload failed (the section serves
 * the last good copy and the module shows "Showing data from {time}").
 */

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { MarketEntry, MarketId } from '@currena/core';
import { formatNumber } from '@currena/core';
import { interpolate } from '../../../i18n';
import type { InsightsCopy } from '../../../i18n/insights-copy-en';
import geo from './world-map-geo.json';
import {
  DEFAULT_PERIOD,
  LAYOUT_SWITCH_PX,
  MAP_CARD_NAME_KEY,
  MAP_CARD_WIDTH_PCT,
  MAP_INDICES,
  MAP_LABELS,
  MAP_LABEL_SIZE_DEFAULT,
  MAP_PERIODS,
  MAP_THRESHOLDS,
  MAP_TINT_COUNTRY_DAMP,
  OPEN_MAX_AGE_MIN,
  borderMixOf,
  inkMixOf,
  mapScaleOf,
  mapWeightOf,
  markMixOf,
  rimMixOf,
  tintMixOf,
  type MapDir,
  type MapPeriod,
} from './world-map-config';
import { isOld, percentGlyph } from './shared';

/* ------------------------------------------------------------------ *
 * The static assets (B3) — one shared in-flight promise, fetched when
 * the module nears the viewport, cached by the browser forever after.
 * ------------------------------------------------------------------ */

interface MapAssets {
  /** One land path per country, ISO-numeric keyed (B1's committed output). */
  land: { iso: string; d: string }[];
  /** The flag sprite's <symbol> markup (B2's committed output). */
  flagsHtml: string;
}

let assetsPromise: Promise<MapAssets> | null = null;

function loadMapAssets(): Promise<MapAssets> {
  if (assetsPromise === null) {
    assetsPromise = (async () => {
      const [mapRes, flagsRes] = await Promise.all([
        fetch('/assets/map/world-map.svg', { cache: 'default' }),
        fetch('/assets/map/world-flags.svg', { cache: 'default' }),
      ]);
      if (!mapRes.ok || !flagsRes.ok) throw new Error('world-map assets unavailable');
      const parser = new DOMParser();
      const mapDoc = parser.parseFromString(await mapRes.text(), 'image/svg+xml');
      const land = Array.from(mapDoc.querySelectorAll('path[data-iso]')).map((p) => ({
        iso: p.getAttribute('data-iso') ?? '',
        d: p.getAttribute('d') ?? '',
      }));
      const flagsDoc = parser.parseFromString(await flagsRes.text(), 'image/svg+xml');
      const flagsRoot = flagsDoc.documentElement;
      const flagsHtml = flagsRoot.innerHTML;
      if (land.length === 0 || flagsHtml.length === 0) throw new Error('world-map assets malformed');
      return { land, flagsHtml };
    })();
    // A failed load must be retryable on the next mount — never a stuck
    // rejected promise the user can never recover from.
    assetsPromise.catch(() => {
      assetsPromise = null;
    });
  }
  return assetsPromise;
}

/* ------------------------------------------------------------------ *
 * Pure display helpers
 * ------------------------------------------------------------------ */

type NumberLocale = 'en-US' | 'fa-IR';
type Locale = 'en' | 'fa';

/** The true minus sign (M15) — never the hyphen-minus. */
const MINUS = '−';

/** D2 at view time: a stored provider "open" only shows while its quote
 * is still OPEN_MAX_AGE_MIN minutes old — the last refresh is the honest
 * clock, so a state frozen at write time can never go stale on screen. */
function openAtViewTime(entry: MarketEntry, nowMs: number): boolean {
  if (entry.open !== true || entry.quoteTime === undefined) return false;
  const age = nowMs - Date.parse(entry.quoteTime);
  return Number.isFinite(age) && age >= -60_000 && age <= OPEN_MAX_AGE_MIN * 60_000;
}

/** 2026-10-27 owner round — the compact D/W/M cells' signed number WITHOUT the
 * percent glyph (the hero row carries the unit loudly; the glyph was
 * what made the old 12.5px triplet overflow its 35px cells — the values
 * ran into each other). The unit rides along as sr-only text so the
 * accessible name still reads "1D +0.7 percent". */
function signedNum(pct: number, numberLocale: NumberLocale): string {
  const num = formatNumber(Math.abs(pct), numberLocale, { minimumFractionDigits: 1, maximumFractionDigits: 1 });
  return `${pct > 0 ? '+' : pct < 0 ? MINUS : ''}${num}`;
}

/** 2026-10-27 — the HERO row's signed percent (the map's loudest number,
 * WITH the unit glyph): a |value| ≥ 100 drops the decimal ("+112%", never
 * "+112.4%") so a five-year return keeps the 14.5%-wide card at every
 * label length — the same honest-compact rule the old cells learned. */
function heroPct(pct: number, numberLocale: NumberLocale, locale: Locale): string {
  const num = formatNumber(Math.abs(pct), numberLocale, {
    minimumFractionDigits: Math.abs(pct) >= 99.95 ? 0 : 1,
    maximumFractionDigits: Math.abs(pct) >= 99.95 ? 0 : 1,
  });
  return `${pct > 0 ? '+' : pct < 0 ? MINUS : ''}${num}${percentGlyph(locale)}`;
}

/** One row of map data, derived purely from the snapshot. */
export interface MapRow {
  id: MarketId;
  /** The registry config row (iso, cc, band, card position). */
  cfg: (typeof MAP_INDICES)[number];
  /** The stored entry — absent when the market has no row at all. */
  entry: MarketEntry | undefined;
  /** Every period's percent change (the cards show D/W/M side by side);
   * null = no honest reading for that period. */
  pcts: Record<MapPeriod, number | null>;
  /** The RELATIVE colour weight per period, 0…1 (2026-10-20f owner round:
   * more down = more red, more up = more saturated green). */
  wts: Record<MapPeriod, number>;
  /** The selected period's direction; null = flat / no data / old —
   * neutral grey pin and card (M17's honest rule). */
  dir: MapDir | null;
  /** The selected period's percent (the summary + sr words read it). */
  pct: number | null;
  /** Old data (last close older than STALE_AFTER_DAYS). */
  old: boolean;
  open: boolean;
}

/** The 3D pin's teardrop in DESIGN units (2026-10-20g owner round): the
 * TIP sits exactly on the index's location, the bulb is centred
 * (0,−9.3) with r 5.2, total height 14.5. Scaled per stage width. */
const PIN_PATH = 'M0 0C-2.3-3.4-5.2-5.6-5.2-9.3A5.2 5.2 0 1 1 5.2-9.3C5.2-5.6 2.3-3.4 0 0Z';

function pctOf(entry: MarketEntry | undefined, period: MapPeriod): number | null {
  if (entry === undefined) return null;
  if (period === '1D') return entry.chg1d;
  if (period === '1W') return entry.chg1w ?? null;
  if (period === '1M') return entry.chg1m ?? null;
  if (period === '3M') return entry.chg3m;
  if (period === '5Y') return entry.chg5y ?? null;
  return entry.chg1y ?? null; // 2026-10-20h: yearly returns to the map
}

/** M10's breadth counts — plain code over the same rows, never a model. */
function summarizeRows(rows: readonly MapRow[], period: MapPeriod) {
  const flatBand = MAP_THRESHOLDS[period];
  let up = 0;
  let down = 0;
  let flat = 0;
  for (const r of rows) {
    const p = r.pcts[period];
    if (p === null) continue;
    if (p > flatBand) up++;
    else if (p < -flatBand) down++;
    else flat++;
  }
  return { up, down, flat, n: up + down + flat };
}

/* ------------------------------------------------------------------ *
 * The module
 * ------------------------------------------------------------------ */

export function WorldMap({
  snapshot,
  fromCache = false,
  loading = false,
  copy,
  locale,
  numberLocale,
  onOpenMarket,
  period: periodProp,
  onPeriodChange,
}: {
  /** The section's stored snapshot (absent in the loading state). */
  snapshot?: { markets: readonly MarketEntry[]; generatedAt: string };
  /** M17: the refresh failed and this is the last good local copy. */
  fromCache?: boolean;
  /** M17's loading state: grey land, grey hollow dots, no numbers. */
  loading?: boolean;
  copy: InsightsCopy;
  locale: Locale;
  numberLocale: NumberLocale;
  /** Opens the index's existing detail view (M13) — the section's own
   * row handler (panel + scroll), exactly like the table's rows. */
  onOpenMarket: (id: MarketId) => void;
  /** 2026-10-21 owner round ("unify the map time views with the other
   * parts of the website"): the switch is now THE section's ONE period
   * control — the shell (WorldMarkets) may own the lens and pass it down
   * (controlled), which also drives the verdict, the movers, the tiles
   * and the table. Absent → the module keeps its own session state
   * (the standalone/loading usage). */
  period?: MapPeriod;
  onPeriodChange?: (p: MapPeriod) => void;
}) {
  const mapCopy = copy.markets.map;
  const rootRef = useRef<HTMLDivElement | null>(null);
  const stageRef = useRef<HTMLDivElement | null>(null);
  const linesGRef = useRef<SVGGElement | null>(null);
  const cardRefs = useRef(new Map<string, HTMLButtonElement>());
  // M11's roving tabindex: the arrow keys must MOVE FOCUS with the
  // selection (the WAI-ARIA radiogroup pattern), not just re-check a
  // distant button.
  const periodBtnRefs = useRef(new Map<MapPeriod, HTMLButtonElement>());

  // M11: session-only period state — no network, no storage, no KV.
  // 2026-10-21: CONTROLLED when the shell passes period/onPeriodChange
  // (the switch drives the whole section then); internal otherwise.
  const [internalPeriod, setInternalPeriod] = useState<MapPeriod>(DEFAULT_PERIOD);
  const period = periodProp ?? internalPeriod;
  const setPeriod = useCallback(
    (p: MapPeriod) => {
      if (onPeriodChange !== undefined) onPeriodChange(p);
      else setInternalPeriod(p);
    },
    [onPeriodChange],
  );
  // M13: the hovered/focused card drives dot + country + line emphasis.
  const [activeId, setActiveId] = useState<MarketId | null>(null);
  const [assets, setAssets] = useState<MapAssets | null>(null);
  const [moduleW, setModuleW] = useState(0);
  const [stageW, setStageW] = useState(0);
  // The viewer's clock, sampled once per mount — the freshness rule's
  // reference (an honest age at every paint the user can act on).
  const [nowMs] = useState(() => Date.now());

  const mapLayout = moduleW >= LAYOUT_SWITCH_PX;
  const todayIso = new Date().toISOString().slice(0, 10);

  /* B3: load the two static assets when the module is about one screen
   * from the viewport (IntersectionObserver, 100% root margin). */
  useEffect(() => {
    const root = rootRef.current;
    if (root === null || assets !== null) return;
    if (typeof IntersectionObserver === 'undefined') {
      void loadMapAssets().then(setAssets).catch(() => undefined);
      return;
    }
    const io = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          io.disconnect();
          void loadMapAssets().then(setAssets).catch(() => undefined);
        }
      },
      { rootMargin: '100% 0px' },
    );
    io.observe(root);
    return () => io.disconnect();
  }, [assets]);

  /* The module's own width (the container query's own value) and the
   * stage's rendered width (the dot radius + leader-line scale). The
   * ResizeObserver reports the initial box on observe, so one observer
   * is the whole measurement story. */
  useEffect(() => {
    if (typeof ResizeObserver === 'undefined') return;
    const root = rootRef.current;
    const stage = stageRef.current;
    if (root === null || stage === null) return;
    const ro = new ResizeObserver(() => {
      setModuleW(root.getBoundingClientRect().width);
      setStageW(stage.getBoundingClientRect().width);
    });
    ro.observe(root);
    ro.observe(stage);
    return () => ro.disconnect();
  }, []);

  /* The rows (§4.1 order = DOM order = tab order), pure derivation. The
   * relative colour scale normalises on the FRESH readings of each period
   * separately (the strongest D mover and the strongest M mover each read
   * weight 1 — "relative" is per lens, never across lenses). */
  const rows = useMemo<MapRow[]>(() => {
    const pctsAll = MAP_INDICES.map((cfg) => {
      const entry = snapshot?.markets.find((m) => m.id === cfg.id);
      const old = !loading && entry !== undefined && isOld(entry, todayIso);
      const pcts = {
        '1D': loading || old ? null : pctOf(entry, '1D'),
        '1W': loading || old ? null : pctOf(entry, '1W'),
        '1M': loading || old ? null : pctOf(entry, '1M'),
        '3M': loading || old ? null : pctOf(entry, '3M'),
        '1Y': loading || old ? null : pctOf(entry, '1Y'),
        '5Y': loading || old ? null : pctOf(entry, '5Y'),
      } as Record<MapPeriod, number | null>;
      return { cfg, entry, old, pcts };
    });
    const scales = {
      '1D': mapScaleOf(pctsAll.map((r) => r.pcts['1D'])),
      '1W': mapScaleOf(pctsAll.map((r) => r.pcts['1W'])),
      '1M': mapScaleOf(pctsAll.map((r) => r.pcts['1M'])),
      '3M': mapScaleOf(pctsAll.map((r) => r.pcts['3M'])),
      '1Y': mapScaleOf(pctsAll.map((r) => r.pcts['1Y'])),
      '5Y': mapScaleOf(pctsAll.map((r) => r.pcts['5Y'])),
    } as Record<MapPeriod, number>;
    return pctsAll.map(({ cfg, entry, old, pcts }) => {
      const wts = {
        '1D': pcts['1D'] === null ? 0 : mapWeightOf(pcts['1D'], '1D', scales['1D']),
        '1W': pcts['1W'] === null ? 0 : mapWeightOf(pcts['1W'], '1W', scales['1W']),
        '1M': pcts['1M'] === null ? 0 : mapWeightOf(pcts['1M'], '1M', scales['1M']),
        '3M': pcts['3M'] === null ? 0 : mapWeightOf(pcts['3M'], '3M', scales['3M']),
        '1Y': pcts['1Y'] === null ? 0 : mapWeightOf(pcts['1Y'], '1Y', scales['1Y']),
        '5Y': pcts['5Y'] === null ? 0 : mapWeightOf(pcts['5Y'], '5Y', scales['5Y']),
      } as Record<MapPeriod, number>;
      const pct = pcts[period];
      const dir: MapDir | null = pct === null || pct === 0 ? null : pct > 0 ? 'u' : 'd';
      return {
        id: cfg.id,
        cfg,
        entry,
        pcts,
        wts,
        dir,
        pct,
        old,
        open: !loading && entry !== undefined && openAtViewTime(entry, nowMs),
      };
    });
  }, [snapshot, period, loading, todayIso, nowMs]);

  const summary = useMemo(() => summarizeRows(rows, period), [rows, period]);

  /* 2026-10-20g owner round — COUNTRY TINTS: a country that hosts several
   * indices (the US trio on New York) tints by its STRONGEST fresh mover
   * in the selected period: the biggest single-index move on screen, never
   * an average no index actually made. Rows with no single country (the
   * Euro Stoxx 50) or no path on the map (Hong Kong) never enter the map. */
  const countryTints = useMemo(() => {
    const best = new Map<string, { dir: MapDir; wt: number }>();
    for (const r of rows) {
      if (r.cfg.iso === null || r.dir === null) continue;
      const cur = best.get(r.cfg.iso);
      if (cur === undefined || r.wts[period] > cur.wt) best.set(r.cfg.iso, { dir: r.dir, wt: r.wts[period] });
    }
    return best;
  }, [rows, period]);

  /* The selected row (hover/focus) drives the country's marching-ants
   * border and its 60%-opacity name; selecting ANY of a country's indices
   * selects the whole country (all three US cards say "USA"). */
  const activeRow = activeId !== null ? rows.find((r) => r.id === activeId) : undefined;
  const activeIso = activeRow !== undefined && activeRow.cfg.iso !== null ? activeRow.cfg.iso : null;

  /* The selected COUNTRY's name label (2026-10-20g): the config's tuned
   * anchor + size when present, else the build-time geo centroid (the
   * largest-polygon one) at the default size. Path-less rows (Hong Kong,
   * the Eurozone) carry an absolute anchor in the config instead. */
  const activeLabel = useMemo(() => {
    if (activeRow === undefined) return null;
    const spec = MAP_LABELS[activeRow.cfg.cc];
    if (spec !== undefined) {
      return { x: (spec.x / 100) * geo.viewBox.width, y: (spec.y / 100) * geo.viewBox.height, size: spec.size, text: mapCopy.countryNames[activeRow.cfg.cc] };
    }
    const gl = activeRow.cfg.iso !== null ? geo.labels[activeRow.cfg.iso as keyof typeof geo.labels] : undefined;
    if (gl === undefined) return null;
    return { x: (gl.x / 100) * geo.viewBox.width, y: (gl.y / 100) * geo.viewBox.height, size: MAP_LABEL_SIZE_DEFAULT, text: mapCopy.countryNames[activeRow.cfg.cc] };
  }, [activeRow, mapCopy]);

  /* M7: leader lines — from each card's nearest edge to its dot, in the
   * map's own coordinate system, recomputed after every layout change.
   * Drawn imperatively into the <g> layer (a measurement effect — no
   * state, no re-render, the §9 layout probe reads the same geometry). */
  useLayoutEffect(() => {
    const g = linesGRef.current;
    if (g === null) return;
    while (g.firstChild !== null) g.removeChild(g.firstChild);
    const stage = stageRef.current;
    if (!mapLayout || loading || stage === null) return;
    const sr = stage.getBoundingClientRect();
    const scale = sr.width / (geo.viewBox.width || 1);
    for (const r of rows) {
      const card = cardRefs.current.get(r.id);
      const dot = geo.dots[r.cfg.id as keyof typeof geo.dots];
      if (card === undefined || dot === undefined) continue;
      const cr = card.getBoundingClientRect();
      const dx = (dot.x / 100) * geo.viewBox.width;
      const dy = (dot.y / 100) * geo.viewBox.height;
      // The card's edges in viewBox units, then the nearest edge point:
      // the dot clamped into the card rect.
      const L = (cr.left - sr.left) / scale;
      const R = (cr.right - sr.left) / scale;
      const T = (cr.top - sr.top) / scale;
      const B = (cr.bottom - sr.top) / scale;
      const x = Math.min(Math.max(dx, L), R);
      const y = Math.min(Math.max(dy, T), B);
      const ln = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      ln.setAttribute('x1', String(x));
      ln.setAttribute('y1', String(y));
      ln.setAttribute('x2', String(dx));
      ln.setAttribute('y2', String(dy));
      ln.setAttribute('data-id', r.id);
      ln.setAttribute('class', `wm-ln ${r.dir !== null ? `s-${r.dir}` : 's-x'}${r.id === activeId ? ' on' : ''}`);
      g.appendChild(ln);
    }
  }, [mapLayout, loading, rows, assets, stageW, period, activeId]);

  /* M13: the list layout's dot tap scrolls to the market's row in the
   * explorer below and flashes it. */
  const onDotClick = useCallback(
    (id: MarketId) => {
      if (mapLayout) return; // the cards are the interactive layer there
      const tile = document.getElementById(`insights-market-tile-${id}`);
      if (tile === null) return;
      tile.scrollIntoView({ block: 'center', behavior: 'smooth' });
      tile.classList.add('wm-flash');
      window.setTimeout(() => tile.classList.remove('wm-flash'), 1600);
    },
    [mapLayout],
  );

  /* Pin scale (2026-10-20g): the design pin is 14.5 viewBox units tall;
   * the RENDERED pin targets ~16px in the map layout and ~12.5px on the
   * phone's list layout (proportionally more units — small maps keep every
   * pin visible and tappable). The hit circle covers the bulb at ≥12px. */
  const unitsPerPx = stageW > 0 ? geo.viewBox.width / stageW : 1;
  const pinK = Math.max(0.55, ((stageW >= LAYOUT_SWITCH_PX ? 16 : 12.5) * unitsPerPx) / 14.5);

  const dirWord: Record<'u' | 'd' | 'x', string> = {
    d: mapCopy.stepFall,
    x: mapCopy.stepFlat,
    u: mapCopy.stepRise,
  };
  const periodLabel: Record<MapPeriod, string> = {
    '1D': mapCopy.periodToday,
    '1W': mapCopy.periodWeek,
    '1M': mapCopy.periodMonth,
    '3M': mapCopy.period3M,
    '1Y': mapCopy.periodYear,
    '5Y': mapCopy.period5Y,
  };
  const periodWord: Record<MapPeriod, string> = {
    '1D': mapCopy.periodWordToday,
    '1W': mapCopy.periodWordWeek,
    '1M': mapCopy.periodWordMonth,
    '3M': mapCopy.periodWord3M,
    '1Y': mapCopy.periodWordYear,
    '5Y': mapCopy.periodWord5Y,
  };
  const cellLabel: Record<MapPeriod, string> = {
    '1D': mapCopy.cellD,
    '1W': mapCopy.cellW,
    '1M': mapCopy.cellM,
    '3M': mapCopy.cell3M,
    '1Y': mapCopy.cellY,
    '5Y': mapCopy.cell5Y,
  };

  const n = (v: number) => formatNumber(v, numberLocale, { maximumFractionDigits: 0 });

  /* M17: "Showing data from {time}" when the refresh failed and the
   * last good local copy is on screen. */
  const showingFrom =
    fromCache && snapshot !== undefined
      ? interpolate(mapCopy.showingFrom, { time: formatRelativeForMap(snapshot.generatedAt, locale) })
      : null;

  return (
    <div ref={rootRef} className="wm @container flex flex-col gap-2" data-wm-layout={mapLayout ? 'map' : 'list'}>
      {/* The flags sprite mounts once, hidden (B2). */}
      {assets !== null ? (
        <svg className="wm-sprite" aria-hidden="true" focusable="false" dangerouslySetInnerHTML={{ __html: assets.flagsHtml }} />
      ) : null}

      {!loading ? (
        <>
          {/* M10 — the one-glance breadth line (NOT the section verdict). */}
          <p className="m-0 text-[length:var(--type-label)] text-[var(--color-text-secondary)]">
            {interpolate(mapCopy.summary, {
              up: n(summary.up),
              n: n(summary.n),
              period: periodWord[period],
              down: n(summary.down),
              flat: n(summary.flat),
            })}
          </p>
          {/* M11 — the six-option segmented control + M17's stale-copy line.
           * 2026-10-20h owner round: the switch CENTRES under the summary
           * (it hugged the start edge before) and grew ~50% — 48px pills,
           * 18.7px words — because the owner asked for bigger and easier
           * to see. Yearly joins as the fourth lens.
           * 2026-10-21 owner round (two asks): (a) "slightly reduce the
           * size of this … like 15%" — the pills drop to 41px (37px under
           * 480px) and the words to caption × 1.27 (× 1.06 on phones);
           * (b) "unify the map time views with the other parts of the
           * website" — this switch is now the SECTION's one period
           * control (the old five-option Daily|Weekly|Monthly|Quarterly|
           * Yearly radiogroup below the movers is retired); when the
           * shell passes onPeriodChange, the same lenses drive the
           * verdict, movers, tiles and table.
           * 2026-10-27 owner round ("add five year and 3 months to all
           * view points"): 3M (the stored chg3m) and 5Y (the job's
           * Yahoo-10y-anchored chg5y) join — six lenses. */}
          <div className="flex flex-wrap items-center justify-center gap-x-3 gap-y-1">
            <div
              role="radiogroup"
              aria-label={mapCopy.periodSwitchAria}
              className="inline-flex max-w-full overflow-x-auto rounded-full bg-currena-soft/70 p-1 ring-1 ring-[var(--color-border)]"
            >
              {MAP_PERIODS.map((p) => {
                const selected = period === p;
                return (
                  <button
                    key={p}
                    type="button"
                    role="radio"
                    aria-checked={selected}
                    tabIndex={selected ? 0 : -1}
                    onKeyDown={(e) => {
                      const at = MAP_PERIODS.indexOf(p);
                      let next: number;
                      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') next = (at + 1) % MAP_PERIODS.length;
                      else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') next = (at - 1 + MAP_PERIODS.length) % MAP_PERIODS.length;
                      else return;
                      e.preventDefault();
                      setPeriod(MAP_PERIODS[next]!);
                      periodBtnRefs.current.get(MAP_PERIODS[next]!)?.focus();
                    }}
                    onClick={() => setPeriod(p)}
                    ref={(el) => {
                      if (el === null) periodBtnRefs.current.delete(p);
                      else periodBtnRefs.current.set(p, el);
                    }}
                    className={`insights-focusable min-h-[41px] cursor-pointer whitespace-nowrap rounded-full px-3.5 py-1 text-[length:calc(var(--type-caption)*1.27)] font-semibold transition-colors @max-[480px]:min-h-[37px] @max-[480px]:px-2.5 @max-[480px]:text-[length:calc(var(--type-caption)*1.06)] ${
                      selected
                        ? 'bg-[var(--color-surface)] text-[var(--color-text-primary)] ring-1 ring-[var(--color-border)]'
                        : 'text-[var(--color-text-secondary)] hover:text-[var(--color-text-primary)]'
                    }`}
                  >
                    {periodLabel[p]}
                  </button>
                );
              })}
            </div>
            {showingFrom !== null ? (
              <span className="text-[length:var(--type-caption)] text-[var(--color-text-tertiary)]">{showingFrom}</span>
            ) : null}
          </div>
        </>
      ) : null}

      {/* The stage: the map box — LTR in both languages, fixed aspect
       * (reserved height in every state, M2/M17). */}
      <div
        ref={stageRef}
        className={`wm-stage ${activeId !== null ? 'hl' : ''}`}
        data-wm-stage=""
      >
        <svg
          className="wm-map"
          viewBox={`0 0 ${geo.viewBox.width} ${geo.viewBox.height}`}
          preserveAspectRatio="xMidYMid meet"
          aria-hidden="true"
          focusable="false"
        >
          {/* M3 — the land: one path per country, visible grey borders
           * (2026-10-20f: the near-white stroke retired for a clear grey),
           * no text. M4 + 2026-10-20g — only the covered countries take a
           * tint (null dir = neutral, honest no-data), its strength
           * relative to the period's biggest move, and a country hosting
           * several indices reads its STRONGEST mover. The selected
           * country wears the marching-ants dash instead of a heavy solid
           * stroke (2026-10-20g: the uneven-looking weight retires). */}
          <g>
            {(assets?.land ?? []).map((p) => {
              const tint = countryTints.get(p.iso);
              const cls = tint !== undefined ? `wm-c s-${tint.dir}` : 'wm-c';
              const on = p.iso === activeIso ? ' on' : '';
              // 2026-10-21 owner round: New York's country (the US trio)
              // damps its mix to 85% — a 15% opacity cut on the loudest
              // fill the map can show (see MAP_TINT_COUNTRY_DAMP).
              const damp = MAP_TINT_COUNTRY_DAMP[p.iso] ?? 1;
              const t = tint !== undefined ? `${Math.round(tintMixOf(tint.wt) * damp * 10) / 10}%` : undefined;
              return <path key={p.iso} data-iso={p.iso} d={p.d} className={`${cls}${on}`} style={t !== undefined ? { ['--t' as string]: t } : undefined} />;
            })}
          </g>
          {/* The selected country's NAME at 60% ink (2026-10-20g owner
           * round — "Brazil / USA / Australia"): decorative (aria-hidden —
           * the card's accessible name already carries the country), one
           * at a time, fading with the selection. */}
          {activeLabel !== null ? (
            <text className="wm-clabel" x={activeLabel.x} y={activeLabel.y} fontSize={activeLabel.size} aria-hidden="true" focusable="false">
              {activeLabel.text}
            </text>
          ) : null}
          {/* M7 — the leader lines (map layout only), drawn imperatively
           * by the measurement effect above (geometry + the active card's
           * emphasis class — hover never triggers a React re-render). */}
          <g ref={linesGRef} className="wm-lines" />
          {/* M5 + 2026-10-20g — one 3D PIN per index (the owner's ask):
           * a FILLED teardrop in the direction colour (green rise / red
           * fall — filled whether open or closed, like a pin on a map), a
           * rim cut stronger than the fill, a specular highlight and a
           * ground shadow for the 3D read. The bulb's inner core keeps
           * the legend's key: solid = open, hollow = closed. */}
          <g>
            {rows.map((r) => {
              const dot = geo.dots[r.cfg.id as keyof typeof geo.dots];
              if (dot === undefined) return null;
              const cx = (dot.x / 100) * geo.viewBox.width;
              const cy = (dot.y / 100) * geo.viewBox.height;
              const dirCls = loading || r.dir === null ? 's-x' : `s-${r.dir}`;
              const m = loading || r.dir === null ? undefined : `${markMixOf(r.wts[period])}%`;
              const m2 = loading || r.dir === null ? undefined : `${rimMixOf(r.wts[period])}%`;
              const k = pinK * (activeId === r.id ? 1.15 : 1);
              const hitR = Math.max(9 * k, 12 * unitsPerPx);
              return (
                <g
                  key={r.id}
                  data-id={r.id}
                  className={`wm-pin ${dirCls}${r.open ? '' : ' closed'}`}
                  transform={`translate(${cx} ${cy})`}
                  style={{ cursor: mapLayout ? 'default' : 'pointer' }}
                  onClick={() => onDotClick(r.id)}
                >
                  {/* The ground shadow anchors the pin on the map. */}
                  <ellipse className="wm-pin-sh" cx={0.5} cy={1.3} rx={3.3 * pinK} ry={1.2 * pinK} />
                  <g className="wm-pin-in" style={{ transform: `scale(${k})`, transformOrigin: '0px 0px' }}>
                    <path
                      className="wm-pin-b"
                      d={PIN_PATH}
                      style={m !== undefined ? { ['--m' as string]: m, ['--m2' as string]: m2 } : undefined}
                    />
                    {/* The specular highlight — the 3D read. */}
                    <ellipse className="wm-pin-hl" cx={-1.8} cy={-11.2} rx={1.9} ry={1.25} transform="rotate(-35 -1.8 -11.2)" />
                    {/* The open/closed core (the legend's key). */}
                    <circle className="wm-pin-core" cx={0} cy={-9.3} r={2} />
                  </g>
                  <circle className="wm-hit" cx={0} cy={-9.3 * k} r={hitR} />
                </g>
              );
            })}
          </g>
        </svg>

        {/* M6/M8 + the 2026-10-20f/h owner rounds — the callout cards, map
         * layout only (the container query hides them below 960px; JS gates
         * the leader lines on the same measured width). DOM order = §4.1
         * order = tab order. Each card carries the YEARLY hero (50% bigger
         * — 2026-10-20h) above the compact Day/Week/Month cells — a
         * triangle (up = green, down = red, flat = a dash bar) and the
         * signed number, the ink's saturation relative to the biggest move
         * in that same period. */}
        {!loading ? (
          <div className="wm-cards absolute inset-0 hidden @min-[960px]:block">
            {rows.map((r) => {
              // §M6: the card's SHORT name — the canonical name unless the
              // config shortens it (only Shanghai Composite does); the
              // accessible name and the explorer below keep the full name.
              const name =
                MAP_CARD_NAME_KEY[r.id] !== undefined ? copy.markets.map[MAP_CARD_NAME_KEY[r.id]!] : copy.markets.entries[r.id].name;
              const country = copy.markets.entries[r.id].country;
              const hasData = r.pct !== null && !r.old;
              const stateWord = !hasData ? (r.old ? mapCopy.oldData : mapCopy.noData) : r.open ? mapCopy.open : mapCopy.closed;
              // M16 + axe's label-in-name rule: NO aria-label — the
              // accessible name derives from the card's CONTENT (the visible
              // strings plus the screen-only glue phrases), so it reads as
              // one sentence and always contains every visible word.
              const srContext = interpolate(mapCopy.srContext, {
                country,
                step: hasData ? dirWord[r.dir ?? 'x'] : stateWord,
              });
              return (
                <button
                  key={r.id}
                  data-id={r.id}
                  ref={(el) => {
                    if (el === null) cardRefs.current.delete(r.id);
                    else cardRefs.current.set(r.id, el);
                  }}
                  type="button"
                  className={`wm-card insights-focusable ${r.dir !== null ? `s-${r.dir}` : 's-x'}${activeId === r.id ? ' on' : ''}`}
                  style={{
                    left: `${r.cfg.card.x}%`,
                    top: `${r.cfg.card.y}%`,
                    width: `${MAP_CARD_WIDTH_PCT}%`,
                    ...(r.dir !== null ? { ['--b' as string]: `${borderMixOf(r.wts[period])}%` } : undefined),
                  }}
                  onMouseEnter={() => setActiveId(r.id)}
                  onMouseLeave={() => setActiveId((cur) => (cur === r.id ? null : cur))}
                  onFocus={() => setActiveId(r.id)}
                  onBlur={() => setActiveId((cur) => (cur === r.id ? null : cur))}
                  onClick={() => onOpenMarket(r.id)}
                >
                  <span className="wm-card-r1">
                    <svg className="wm-flag" viewBox="0 0 512 512" aria-hidden="true" focusable="false">
                      <use href={`#wm-flag-${r.cfg.cc}`} />
                    </svg>
                    <span className="wm-card-name">{name}</span>
                    <span className="sr-only">{srContext}</span>
                    <span className={`wm-tag${r.open && hasData ? ' o' : ''}`} title={stateWord}>
                      <i aria-hidden="true" />
                      {/* 2026-10-20f: the common Open/Closed states speak as the
                       * legend-keyed dot (the word stays in the accessible
                       * name); only the abnormal No data / Old data states
                       * spend the card width on their words. */}
                      {hasData ? <span className="sr-only">{stateWord}</span> : stateWord}
                    </span>
                  </span>
                  <span className="sr-only">{mapCopy.srPerf}</span>
                  {/* 2026-10-20h owner round — the YEARLY hero row: the
                   * app's NORMAL horizon, 50% bigger than the old numbers
                   * ("add yearly performance and make it 50% bigger and
                   * easier to see"), triangle + signed percent in the
                   * direction ink. 2026-10-27 owner round ("add five year
                   * and 3 months to all view points"): the hero FOLLOWS THE
                   * SELECTED LENS — six horizons can never fit one
                   * 14.5%-wide card as glyph rows (five cells ≈ 160px vs
                   * the ~117px inner width), so every lens takes its turn
                   * as the loud number: the map's tints, pins and summary
                   * speak the selected period, and now every card's hero
                   * number agrees. The 1Y directive is honoured exactly
                   * whenever 1Y is selected; D/W/M keep their classic
                   * compact cells below. */}
                  {(() => {
                    const pct = r.pcts[period];
                    const missing = pct === null;
                    const dir: 'u' | 'd' | null = missing || pct === 0 ? null : pct > 0 ? 'u' : 'd';
                    const tri =
                      dir === 'u' ? (
                        <path d="M5 1 9.5 9H.5z" />
                      ) : dir === 'd' ? (
                        <path d="M.5 1h9L5 9z" />
                      ) : (
                        <rect x="0.5" y="3.5" width="9" height="3" rx="1" />
                      );
                    const yi = dir !== null ? `${inkMixOf(r.wts[period])}%` : undefined;
                    return (
                      <span data-p={period} className="wm-yrow sel">
                        <i className="wm-pl">{cellLabel[period]}</i>
                        <b className={`wm-pv wm-yv${dir !== null ? ` s-${dir}` : ' s-x'}`} style={yi !== undefined ? { ['--i' as string]: yi } : undefined}>
                          {missing ? (
                            <bdi dir="ltr">—</bdi>
                          ) : (
                            <>
                              <svg className="wm-ar2" viewBox="0 0 10 10" aria-hidden="true" focusable="false" width="13" height="13">
                                {tri}
                              </svg>
                              <bdi dir="ltr">{heroPct(pct, numberLocale, locale)}</bdi>
                            </>
                          )}
                        </b>
                      </span>
                    );
                  })()}
                  {/* The classic compact Day/Week/Month cells — the percent
                   * glyph moved into the hero (and sr-only here): the glyph
                   * is what made the old 12.5px values overrun their 35px
                   * cells and run into each other. 2026-10-27: unchanged —
                   * the 3M/1Y/5Y horizons surface through the hero row
                   * above (the selected lens), keeping the card at its
                   * tuned height. */}
                  <span className="wm-tri">
                    {(['1D', '1W', '1M'] as const satisfies readonly MapPeriod[]).map((p) => {
                      const pct = r.pcts[p];
                      const missing = pct === null;
                      const dir: 'u' | 'd' | null = missing || pct === 0 ? null : pct > 0 ? 'u' : 'd';
                      const tri =
                        dir === 'u' ? (
                          <path d="M5 1 9.5 9H.5z" />
                        ) : dir === 'd' ? (
                          <path d="M.5 1h9L5 9z" />
                        ) : (
                          <rect x="0.5" y="3.5" width="9" height="3" rx="1" />
                        );
                      const i = dir !== null ? `${inkMixOf(r.wts[p])}%` : undefined;
                      return (
                        <span key={p} data-p={p} className={`wm-cell${p === period ? ' sel' : ''}`}>
                          <i className="wm-pl">{cellLabel[p]}</i>
                          <b className={`wm-pv${dir !== null ? ` s-${dir}` : ' s-x'}`} style={i !== undefined ? { ['--i' as string]: i } : undefined}>
                            {missing ? (
                              <bdi dir="ltr">—</bdi>
                            ) : (
                              <>
                                <svg className="wm-ar2" viewBox="0 0 10 10" aria-hidden="true" focusable="false" width="7" height="7">
                                  {tri}
                                </svg>
                                <bdi dir="ltr">{signedNum(pct, numberLocale)}</bdi>
                                <span className="sr-only">%</span>
                              </>
                            )}
                          </b>
                        </span>
                      );
                    })}
                  </span>
                  {/* 2026-10-20h: the last close rides in the accessible
                   * name only — the visible card speaks the name, the
                   * state and the four performance horizons; the explorer
                   * and the detail view carry the close. */}
                  {hasData && r.entry !== undefined ? (
                    <span className="sr-only">
                      {mapCopy.srVal} {fmtValue(r.entry, numberLocale)}
                    </span>
                  ) : null}
                </button>
              );
            })}
          </div>
        ) : null}
      </div>

      {/* M12 + the 2026-10-20f owner round — one inline legend row: the
       * relative-scale key (a red→grey→green gradient: the further from
       * flat, the stronger the colour), then the open/closed dot key. */}
      {!loading ? (
        <div className="wm-legend">
          <span className="wm-lg">
            <em>{mapCopy.legendMoreDown}</em>
            <i className="wm-grad" aria-hidden="true" />
            <em>{mapCopy.legendMoreUp}</em>
          </span>
          <span>
            <i className="wm-kdot o" aria-hidden="true" />
            {mapCopy.open}
          </span>
          <span>
            <i className="wm-kdot" aria-hidden="true" />
            {mapCopy.closed}
          </span>
        </div>
      ) : null}
    </div>
  );
}

/* ------------------------------------------------------------------ *
 * Formatting helpers shared by the module's own surfaces
 * ------------------------------------------------------------------ */

/** The last close, the section's own presentation (no new dialect). */
function fmtValue(entry: MarketEntry, numberLocale: NumberLocale): string {
  return formatNumber(entry.close, numberLocale, { maximumFractionDigits: entry.close >= 1000 ? 0 : 2 });
}

/** M17/M9's relative clock for the "Showing data from {time}" line. */
function formatRelativeForMap(iso: string, locale: Locale): string {
  const tag = locale === 'fa' ? 'fa-IR-u-ca-persian' : 'en-US';
  return new Intl.DateTimeFormat(tag, { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(iso));
}
